let submitting = false
export async function submit(send) {
  if (submitting) return
  submitting = true
  try { await send() } finally { submitting = false }
}

test("duplicate submission", async () => {
  await Promise.all([submit(send), submit(send)])
  expect(send).toHaveBeenCalledTimes(1)
})

